'use strict';
const C=window.COMMUNITY,R=window.COMMUNITY_V2,Art=window.CommunityArt,$=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SOURCES={...C.sources,...R.sources},cats=Object.fromEntries(C.categories.map(c=>[c[0],c]));
const readLocal=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},writeLocal=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}};
const ARTICLES=[...C.articles.map(a=>({id:a[0],cat:a[1],title:a[2],audience:a[3],hook:a[4],actions:a[5],avoid:a[6],warning:a[7],sources:a[9],...R.details[a[0]]})),...R.extra];
const byId=Object.fromEntries(ARTICLES.map(a=>[a.id,a]));
let saved=readLocal('nur-community-saved',[]);if(!Array.isArray(saved))saved=[];saved=saved.filter(id=>byId[id]);
let fontLevel=Number(readLocal('nur-community-font-v2',0));if(![0,1,2].includes(fontLevel))fontLevel=0;
let pathFilter='all',category='all',query='',visible=12,installEvent=null,activeTopic=null;
const safeStorage={getItem:k=>{try{return localStorage.getItem(k)}catch{return null}},setItem:(k,v)=>localStorage.setItem(k,v),removeItem:k=>localStorage.removeItem(k)};
const scenarioById=Object.fromEntries(window.CommunityScenarios.items.map(s=>[s.id,s]));
const simulationRecords=new window.CommunitySimulation.Records(safeStorage);
let simulationRun=null;
const surveyStore=new window.CommunitySurvey(safeStorage);
const measurement=new window.CommunityMeasure(safeStorage),featured=['pcos','child-tonsillitis','migraine','sinusitis','eczema','diabetes','blood-pressure','kidney-disease','gout','women-health','mental-anxiety','addiction-help','diabetes-sick-days','diabetes-food-portions','diabetes-high-correction','h-pylori','school-day','home-kit','produce-pesticides','health-waste','conserve-water'];
const listHTML=items=>'<ul>'+items.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul>';
const normalize=s=>String(s).toLowerCase().normalize('NFKD').replace(/[\u064b-\u065f\u0670]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/ـ/g,'');
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function applyFont(){document.documentElement.setAttribute('data-font',String(fontLevel));$('#fontSize').textContent=['نص أكبر +','نص أكبر ++','الحجم العادي'][fontLevel];$('#fontSize').setAttribute('aria-label','تغيير حجم النص الحالي '+['عادي','كبير','أكبر'][fontLevel]);}
function star(id){return `<button class="bookmark" data-save="${id}" aria-label="${saved.includes(id)?'إزالة من':'إضافة إلى'} المحفوظات" aria-pressed="${saved.includes(id)}">${saved.includes(id)?'★':'☆'}</button>`}
function card(a){return `<article class="story-card"><a href="#topic=${a.id}" class="card-art">${Art.render(a.art,a.title)}</a><div class="card-copy"><div class="card-top"><span class="label">${esc(cats[a.cat][1])}</span>${star(a.id)}</div><a href="#topic=${a.id}"><h3>${esc(a.title)}</h3><p>${esc(a.hook)}</p><span class="read">افتح الموضوع ←</span></a></div></article>`}
function home(){return `<section class="hero-v2"><div class="hero-photo"><img src="assets/community-hero-arm-support.webp" alt="صورة تخيلية لممرض شاب يسند ذراع رجل مسن أثناء سيرهما، يظهران من الخلف دون الوجهين" width="1536" height="1024" fetchpriority="high"></div><div class="hero-copy"><span class="eyebrow">تمريض من أجل المجتمع</span><h1 class="solidarity-headline">الوعي والسلوك المجتمعي<br>هو خط الدفاع الأول</h1><p>نحوّل المعرفة إلى عادات صحية، ونرعى الإنسان والبيئة بروح التكافل.</p><a class="button primary" href="#explore">ابدأ من موضوع يهمك ←</a><a class="hero-sim-link" href="#simulations">أو جرب موقفًا تفاعليًا ←</a></div></section>${trialNotice()}<section class="student-intro"><div><b>طلابنا يمارسون دورهم المجتمعي بنشر التوعية الصحية</b><p>مبادرة من كلية التمريض، جامعة طبرق، تحت إشراف قسم خدمة المجتمع وأساتذتهم. جهود ذاتية دون دعم مادي، نطورها لنتعلم ونخدم الناس. إذا وجدت خطأً أو كان لديك نقد أو اقتراح، وجّهه إلينا.</p></div><a class="button soft" href="#feedback">رأيك يساعدنا</a></section><section id="explore"><div class="section-title"><div><span class="label">كل المجالات أمامك</span><h2>اختر موضوع صحتك</h2></div><span class="muted">${ARTICLES.length} موضوعًا مصورًا</span></div>${healthHubs()}<details class="audience-paths"><summary>أو اختر من حياتك اليومية: البيت، المدرسة، الأسرة…</summary><div class="life-paths"><button data-path="all" aria-pressed="${pathFilter==='all'}">كل الموضوعات</button>${R.paths.map(p=>`<button data-path="${p[0]}" aria-pressed="${pathFilter===p[0]}"><b>${p[1]}</b><small>${p[2]}</small></button>`).join('')}</div></details><div class="search-tools"><div class="searchbox"><span aria-hidden="true">⌕</span><input type="search" id="search" aria-label="ابحث بكلمة أو سؤال" placeholder="اكتب: السكري، الضغط، الكلى، صحة المرأة…" value="${esc(query)}"><button id="clearSearch" aria-label="مسح البحث">مسح</button></div><label class="category-select" for="category">أو اختر مجالًا<select id="category"><option value="all">جميع المجالات</option><optgroup label="وصول مباشر">${R.healthHubs.filter(h=>h.ids).map(h=>`<option value="${h.value}" ${category===h.value?'selected':''}>${h.label}</option>`).join('')}</optgroup><optgroup label="المجالات الصحية">${C.categories.map(c=>`<option value="${c[0]}" ${c[0]===category?'selected':''}>${c[1]}</option>`).join('')}</optgroup></select></label></div><div class="results-head" id="resultsStart"><a href="#explore">تغيير المجال ↑</a><span id="resultCount" role="status" aria-live="polite"></span><button id="allTopics">عرض الجميع</button></div><div id="cards" class="cards"></div><div class="more-wrap"><button id="loadMore" class="button" hidden>موضوعات أكثر ↓</button></div></section>${simulationTeaser()}<section class="featured-tool"><div><span class="label">جرب شيئًا عمليًا الآن</span><h2>هل صيدلية البيت مرتبة وآمنة؟</h2><p>تفقد بسيط للأدوات والصلاحية وطريقة الحفظ. يمكنك إعادته كلما احتجت.</p><a href="#topic=home-kit" class="button primary">افتح قائمة التفقد</a></div><div>${Art.render('kit','رسم لمستلزمات صيدلية المنزل')}</div></section><section class="help-strip"><div><h2>هناك علامات لا تنتظر</h2><p>فقد الوعي، ضيق النفس الشديد، ألم الصدر أو نزف شديد: اطلب المساعدة فورًا.</p></div><a class="button" href="#urgent">اعرف كيف تطلب المساعدة</a></section>`}
function results(){const terms=normalize(query).split(/\s+/).filter(Boolean);let list=ARTICLES.filter(a=>(pathFilter==='all'||a.tags.includes(pathFilter))&&(category==='all'||(R.healthHubs.find(h=>h.value===category)?.ids?.includes(a.id))||a.cat===category)&&terms.every(t=>normalize([articleText(a),cats[a.cat][1],R.searchAliases[a.id]||'',a.id==='h-pylori'?'بكتيريا المعدة الميكروب الحلزوني':''].join(' ')).includes(t)));if(!query)list.sort((a,b)=>(featured.includes(a.id)?featured.indexOf(a.id):-1+999)-(featured.includes(b.id)?featured.indexOf(b.id):-1+999));$('#cards').innerHTML=list.length?list.slice(0,visible).map(card).join(''):'<div class="empty"><h2>لم نجد نتيجة بهذه الكلمات</h2><p>جرب كلمة أبسط أو اعرض كل الموضوعات.</p></div>';$('#resultCount').textContent=`${category==='all'?'كل المجالات':(R.healthHubs.find(h=>h.value===category)?.label||cats[category]?.[1]||'الموضوعات')} · ${list.length} موضوعًا${query?' يطابق بحثك':''} · المعروض ${Math.min(visible,list.length)}`;$('#loadMore').hidden=list.length<=visible;document.querySelectorAll('[data-path]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.path===pathFilter));document.querySelectorAll('[data-health-hub]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.healthHub===category));}
function articleText(a){return [a.title,a.hook,'الفكرة ببساطة',a.about,'ما الذي تلاحظه؟',...a.symptoms,'خطوات يمكنك فعلها',...a.actions,'للوقاية',...a.prevention,...(a.learningSections||[]).flatMap(s=>[s.title,s.body||'',...(s.bullets||[])]),'عن العلاج والرعاية',a.treatment,'تجنب',a.avoid,'متى تطلب المساعدة؟',a.warning,'مثال من الحياة',a.scene].join('. ')}
function kitTool(){const checked=readLocal('nur-community-kit',[]);return `<section class="interactive-block"><span class="label">قائمة قابلة للتكرار</span><h2>تفقد صيدلية البيت</h2><p>ضع علامة أمام ما تحققت منه. تحفظ العلامات على جهازك، ولا ترسل إلى الكلية.</p><div class="checklist">${R.kit.map((s,i)=>`<label><input type="checkbox" data-kit="${i}" ${Array.isArray(checked)&&checked.includes(i)?'checked':''}><span>${s}</span></label>`).join('')}</div><div class="tool-actions"><button id="kitDone" class="button primary">أنهيت التفقد اليوم</button><button id="kitReset">بدء تفقد جديد</button></div><p id="kitStatus" role="status">${esc(readLocal('nur-community-kit-date','')?'آخر تفقد على هذا الجهاز: '+readLocal('nur-community-kit-date',''):'أعد التفقد دوريًا وبعد استخدام الأدوات.')}</p></section>`}
function waterTool(){return `<section class="interactive-block"><h2>اجعل الماء في طريقك</h2><p>اختر تذكيرًا يوميًا يناسبك، دون فرض كمية لا تلائم حالتك.</p><div class="choice-row">${['مع الوجبات','في استراحة العمل','عند العودة من مشوار'].map(s=>`<button data-water="${s}" aria-pressed="false">${s}</button>`).join('')}</div><p id="waterChoice" role="status">هذا اختيار لهذه الصفحة؛ لا ينشئ تنبيهًا ولا يغير تقييد السوائل الموصوف.</p></section>`}
function topic(id){const a=byId[id];if(!a)return '<div class="empty"><h1>هذا الموضوع غير موجود</h1><a href="#home">العودة للبداية</a></div>';activeTopic=id;return `<article class="article-v2"><a class="back" href="#home">→ الموضوعات</a><div class="topic-hero"><div><span class="label">${esc(cats[a.cat][1])}</span><h1>${esc(a.title)}</h1><p class="topic-hook">${esc(a.hook)}</p><div class="article-actions"><button class="button primary" id="readTopic">◖ استمع للموضوع</button>${star(id)}<button id="share" data-id="${id}">شارك</button><button id="showSources" class="quiet-source-button">مصادر المعلومات</button></div><p class="audience">${esc(a.audience)} · قراءة نحو ${Math.max(2,Math.ceil(articleText(a).split(/\s+/).length/110))} دقائق</p></div><div class="topic-art">${Art.render(a.art,a.title)}</div></div>${diabetesShortcuts(a)}<div class="early-measure"><span>تريد مقارنة فهمك قبل القراءة وبعدها؟ المشاركة اختيارية.</span><a href="#measure=${id}&stage=before">ابدأ بسؤال قصير ←</a></div><div id="readable"><section class="intro-text"><h2>الفكرة ببساطة</h2><p>${esc(a.about)}</p>${sectionRefs(a,'about')}</section><div class="topic-grid"><section class="article-block signs"><span class="section-number">01</span><h2>ما الذي قد تلاحظه؟</h2>${listHTML(a.symptoms)}${sectionRefs(a,'symptoms')}</section><section class="article-block actions"><span class="section-number">02</span><h2>خطوات يمكنك فعلها</h2><ol>${a.actions.map(s=>'<li>'+esc(s)+'</li>').join('')}</ol>${sectionRefs(a,'actions')}</section></div><section class="prevention-block"><div>${Art.render(a.art==='cleaning'?'hands':a.art==='stomach'?'foodsafe':a.art,'رسم مرتبط بالوقاية')}</div><div><span class="label">الوقاية والسلوك اليومي</span><h2>ما الذي يقلل الخطر؟</h2>${listHTML(a.prevention)}${sectionRefs(a,'prevention')}</div></section>${learningSections(a)}<section class="treatment-block"><span class="label">معلومة تساعدك على فهم الرعاية</span><h2>عن العلاج</h2><p>${esc(a.treatment)}</p>${sectionRefs(a,'treatment')}</section><div class="topic-grid"><section class="avoid-block"><h2>انتبه لهذا التصرف</h2><p>${esc(a.avoid)}</p>${sectionRefs(a,'avoid')}</section><section class="warning-block"><h2>متى تطلب المساعدة؟</h2><p>${esc(a.warning)}</p>${sectionRefs(a,'warning')}</section></div><section class="life-scene"><span class="label">من الحياة اليومية</span><h2>موقف قد يحدث عندنا</h2><p>${esc(a.scene)}</p>${sectionRefs(a,'scene')}</section></div>${a.tool==='kit'?kitTool()+sectionRefs(a,'actions'):a.tool==='water'?waterTool()+sectionRefs(a,'actions'):''}${relatedTopics(a)}<section class="next-action"><div><h2>ما الخطوة التي ستأخذها معك؟</h2><p>تأكد من فهم الفكرة، أو أخبرنا إن لم تكن واضحة. يمكنك العودة والمشاركة أكثر من مرة.</p></div><div class="choice-row"><a class="button primary" href="#measure=${id}&stage=after">تأكد من فهمك</a><a class="button" href="#measure=${id}&stage=followup">شارك ما طبقته لاحقًا</a><a class="button" href="#feedback=${id}">ملاحظة أو تصحيح</a></div></section><details class="source-details" id="topicSources"><summary>المصادر وحالة المراجعة</summary><ul class="source-list">${articleSourceKeys(a).map(k=>SOURCES[k]).filter(Boolean).map(s=>`<li><a href="${esc(s[2])}" target="_blank" rel="noopener noreferrer">${esc(s[0])} · ${esc(s[1])} ↗</a></li>`).join('')}</ul><p>إصدار ${R.version} · إعداد وتحقق من الروابط ${R.date}. صياغة عربية أولية بانتظار مراجعة الكلية المختصة؛ لا توجد أسماء مراجعين أو طلاب منسوبة قبل توثيق عملهم.</p></details><div class="article-actions"><button id="print">طباعة الموضوع</button><a class="button" href="#home">موضوع آخر</a></div></article>`}
function urgent(){return `<div class="page-head"><h1>إذا كان هناك خطر، اتصل الآن</h1><p>لا تنتظر استكمال قراءة التطبيق عند وجود حالة طارئة.</p></div><div class="warning-block urgent-large"><h2>فقد الوعي أو عدم التنفس طبيعيًا</h2><p>اطلب الإسعاف المحلي فورًا واتبع تعليمات المجيب. إذا كان الشخص لا يستجيب ولا يتنفس طبيعيًا، ابدأ الإنعاش حسب تدريبك أو إرشاد المجيب واستعمل جهاز الصدمات إن توفر. لا تعطِ فاقد الوعي شيئًا بالفم.</p></div><div class="topic-grid"><section class="article-block"><h2>ماذا أقول عند الاتصال؟</h2><ol><li>الموقع وأقرب علامة معروفة.</li><li>ما حدث، وعدد المصابين إن وجد.</li><li>هل يستجيب الشخص ويتنفس؟</li><li>استخدم مكبر الهاتف واتبع التعليمات.</li></ol></section><section class="article-block"><h2>احم نفسك أيضًا</h2><p>لا تدخل مكانًا به كهرباء أو نار أو غازات مؤذية دون تأمينه. رقم الطوارئ ومسار الإحالة المحلي يضافان بعد التحقق من الجهة المختصة.</p></section></div>${referenceDetails([SOURCES.urgentFirstAid],'مصادر الإسعافات الأولية')}<div class="cards">${['stroke','bleeding','burns','heat','maternal-danger','child-dehydration'].map(id=>card(byId[id])).join('')}</div>`}
function feedbackLink(payload){const f=R.feedback.fields,u=new URL(R.feedback.url);u.searchParams.set('usp','pp_url');const values={category:'البوابة الإلكترونية/الخدمات الرقمية',year:'أفضل عدم التحديد',date:new Date().toLocaleDateString('ar-LY'),message:payload.message,recurrence:payload.recurrence||'مشاركة مفتوحة قابلة للتكرار في مبادرة التوعية المجتمعية',previous:'أرسلت عبر تطبيق تمريض من أجل المجتمع؛ يرجى تصنيفها ضمن خدمة المجتمع.',suggestion:payload.suggestion||'',contact:'لا'};Object.entries(values).forEach(([k,v])=>u.searchParams.set('entry.'+f[k],v));return u.href;}
function measurePage(id,stage){const a=byId[id];if(!a)return '<div class="empty">اختر موضوعًا أولًا. <a href="#home">الموضوعات</a></div>';const n=measurement.rows.filter(r=>r.topic===id).length;return `<div class="narrow"><a class="back" href="#topic=${id}">→ العودة للموضوع</a><div class="page-head"><span class="label">دقيقة اختيارية للفهم والمتابعة</span><h1>${stage==='followup'?'ماذا طبقت بعد القراءة؟':'تأكد من الفكرة الأساسية'}</h1><p>${esc(a.title)}. يمكنك تكرار المشاركة في زيارة أخرى أو بعد نشاط جديد.</p></div><form id="measureForm" class="panel form-panel" data-topic="${id}"><label class="field" for="measureStage">متى تشارك؟</label><select id="measureStage" name="stage"><option value="before" ${stage==='before'?'selected':''}>قبل قراءة الموضوع</option><option value="after" ${stage==='after'?'selected':''}>بعد قراءة الموضوع</option><option value="followup" ${stage==='followup'?'selected':''}>متابعة لاحقة بعد فرصة للتطبيق</option></select><fieldset><legend>${esc(a.question[0])}</legend>${a.question[1].map((s,i)=>`<label class="radio-choice"><input type="radio" name="answer" value="${i}" required><span>${esc(s)}</span></label>`).join('')}</fieldset><label class="field" for="confidence">ما مدى ثقتك بفهم التصرف الصحيح؟</label><select id="confidence" name="confidence" required><option value="">اختر</option><option value="1">ما زلت غير متأكد</option><option value="2">فهمت جزءًا وأحتاج توضيحًا</option><option value="3">أستطيع شرح الفكرة لشخص آخر</option></select><label class="field" for="behavior">وبالنسبة إلى خطوة عملية من الموضوع؟</label><select id="behavior" name="behavior" required><option value="">اختر</option><option value="plan">أنوي تطبيق خطوة</option><option value="done">طبقت خطوة بالفعل</option><option value="notyet">لم أطبق بعد</option><option value="notrelevant">لا تنطبق علي الآن</option></select><label class="field" for="campaign">رمز النشاط إذا أعطاك الفريق رمزًا — اختياري</label><input type="text" id="campaign" name="campaign" maxlength="24" placeholder="اتركه فارغًا عند القراءة الفردية"><label class="consent"><input name="linkPrevious" type="checkbox"> هذه متابعة لإجابتي القبلية السابقة في الموضوع نفسه ورمز النشاط نفسه على هذا الجهاز. اتركها دون تحديد لمشاركة مستقلة.</label><label class="consent"><input name="consent" type="checkbox" required> أوافق على حفظ هذه الإجابة دون اسم على هذا الجهاز. إرسالها للكلية خيار منفصل.</label><button class="button primary" type="submit">احفظ المشاركة</button><p class="form-note">المحفوظ هنا لهذا الموضوع: ${n} سجلات. لا يوجد قيد «مرة واحدة». لا ترسل الإجابات تلقائيًا ولا تعني عدد أشخاص مختلفين.</p></form><div id="measureResult" aria-live="polite"></div></div>`}
function dashboard(){const s=measurement.summary();return `<div class="page-head"><span class="label">أدوات فريق المبادرة</span><h1>متابعة متكررة على هذا الجهاز</h1><p>الأرقام لهذا المتصفح فقط؛ لا تمثل الوصول العام أو عدد المستفيدين. المشاركات التي يكمل الزوار إرسالها لنموذج الكلية تبقى في سجلها المركزي.</p></div><div class="metric-grid"><div><b>${s.records}</b><span>سجل اختياري محفوظ</span></div><div><b>${s.paired}</b><span>دورة لها قياس قبلي وبعدي مطابقان</span></div><div><b>${s.change===null?'—':s.change.toFixed(1)}</b><span>فرق صحة الإجابة بالنقاط المئوية</span></div><div><b>${s.followup?s.action+' / '+s.followup:'—'}</b><span>دورات متابعة أفادت بتطبيق خطوة</span></div></div><section class="panel"><h2>كيف نقرأ النتائج؟</h2><p>تُطابق الإجابات داخل دورة الموضوع ورمز النشاط والإصدار والسؤال نفسه؛ يؤخذ آخر قياس من كل مرحلة. السلوك والثقة بلاغ ذاتي. رؤية الإجابة وتكرار الاختبار يؤثران في التعلم، فلا يفسر الفرق وحده كأثر سببي أو صحي للتطبيق.</p><div class="choice-row"><button id="exportMetrics" class="button primary">تصدير سجل CSV</button><button id="clearMetrics">مسح السجل المحلي</button><a class="button" href="measurement-protocol.md">دليل القياس والتوثيق</a></div><p id="clearMetricsPrompt" role="status"></p></section><details><summary>البيانات المركزية والتوثيق</summary><p>بعد حفظ إجابته يمكن للزائر فتح نموذج الكلية برسالة منظمة تبدأ NUR_COMMUNITY_MEASURE. يكتمل الإرسال في نموذج Google. تحمل المشاركة الوقت والموضوع والإصدار ونوع القياس ورمز الدورة، لتصنيفها لاحقًا في منظومة الجودة. لا ترسل السجلات في الخلفية.</p></details><details><summary>إغلاق دورة التحسين ثم إعادة القياس</summary><p>راجع الملاحظات شهريًا: المشكلة والسبب والإجراء والمسؤول والموعد والدليل ثم إعادة القياس. كرر الدورة مع كل حملة، ولا تدمج إصدارات أو جماهير دون بيان. <a href="improvement-register.csv" download>تنزيل سجل تحسين فارغ</a>.</p></details>${simulationDashboard()}${surveyDashboard()}<section class="panel"><h2>سجلات العمل</h2><div class="choice-row"><a class="button" href="review-register.csv" download>مراجعة المحتوى</a><a class="button" href="activity-record.csv" download>الأنشطة والنتائج الإجمالية</a><a class="button" href="#students">الطلاب والمشرفون</a></div></section>`}
function students(){return `<div class="page-head"><h1>الطلاب والمشرفون</h1><p>اختاروا حاجة حقيقية من أسئلة الناس، وأعدوا محتوى عمليًا، ثم اختبروا وضوحه وحدثوه بناءً على الملاحظات.</p></div><div class="topic-grid"><section class="panel"><h2>دورة عمل مستمرة</h2><ol><li>اسمع الاحتياج وحدد الجمهور.</li><li>راجع مصدرًا رسميًا واكتب مثالًا من الحياة.</li><li>اعرض الدقة وعلامات الخطر على أستاذ مختص.</li><li>اختبر الفهم وأصلح ما التبس.</li><li>سجل المساهمات والموافقة وانشر الإصدار.</li><li>تابع التعلم والسلوك وأعد القياس بعد التحسين.</li></ol></section><section class="panel english" lang="en" dir="ltr"><h2>Students and supervisors</h2><p>Prepare original plain-language education from authoritative sources. Include symptoms, warning signs, prevention, practical actions and safe treatment information. Obtain subject review and publication approval. Credit real contributions only after consent.</p><p>Feedback remains open to repeated contributions. Optional assessments record topic, release, stage, anonymous cycle and campaign code. Local records stay on the device until exported or explicitly shared through the faculty form. No background transmission takes place.</p></section></div><section class="panel"><h2>التوثيق والمتابعة</h2><div class="choice-row"><a class="button primary" href="#dashboard">سجل المتابعة على هذا الجهاز</a><a class="button" href="review-register.csv" download>سجل المراجعة</a><a class="button" href="plan.html">خطة البداية</a></div><p>المحتوى بانتظار مراجعة الكلية. رسم الواجهة تخيلي ولا يمثل طلابًا أو مستفيدين حقيقيين. لا تنشر بيانات مرضى أو صورًا دون موافقات مناسبة.</p></section>`}
function about(){return `<div class="page-head"><h1>عن المبادرة وسهولة الاستخدام</h1><p>جهود ذاتية لطلاب كلية التمريض بجامعة طبرق، بإشراف قسم خدمة المجتمع والأساتذة، لنشر وعي صحي عملي دون دعم مادي.</p></div><section class="panel"><h2>القراءة بصوت</h2><p>اضغط «استمع للموضوع». يعتمد الصوت العربي على أصوات هاتفك أو متصفحك؛ يمكنك اختيار الصوت والسرعة. إن لم يتوفر صوت عربي تظهر رسالة، ويمكن إضافة صوت عربي من إعدادات الجهاز. بعض الأصوات تعمل محليًا وبعضها يحتاج اتصالًا وخدمة الجهاز.</p><h2>إضافة إلى الهاتف</h2><p>في Android اختر التثبيت أو الإضافة إلى الشاشة الرئيسية من قائمة المتصفح. في Safari على iPhone: مشاركة ثم إضافة إلى الشاشة الرئيسية. بعد التحميل الكامل تتاح المواد والرسوم المضمنة دون اتصال؛ المصادر ونموذج الكلية يحتاجان اتصالًا.</p><h2>خصوصيتك واختياراتك</h2><p>المفضلة وحجم الخط وتفقد الصيدلية تبقى على الجهاز. لا نسجل زيارات أو هوية في الخلفية. القياس يحفظ بموافقتك، وإرساله للكلية يحتاج اختيارًا آخر وإتمام النموذج. قد يحتفظ المضيف بسجلات تشغيله المعتادة.</p><button id="resetPreferences">مسح المفضلة وإعدادات النص</button><h2>المحتوى والمراجعة</h2><p>لكل مادة مصادر وحالة مراجعة. المعلومات تشرح الوقاية والرعاية والعلاج العام ولا تحدد وصفة أو جرعة شخصية. المراجعة العلمية واللغوية للكلية مطلوبة قبل الإطلاق الرسمي.</p></section><div class="choice-row"><a class="button" href="#feedback">نقد أو اقتراح</a><a class="button" href="#students">الطلاب والمشرفون</a><a class="button" href="#dashboard">أدوات المتابعة</a></div>`}
function route(){stopReading();let h=location.hash.slice(1)||'home';const params=new URLSearchParams(h),topicId=params.get('topic'),feedbackId=params.get('feedback'),measureId=params.get('measure'),simId=params.get('sim');const key=simId?'sim':topicId?'topic':h.startsWith('feedback')?'feedback':measureId?'measure':h==='explore'?'home':h;activeTopic=null;const main=$('#main');if(key!=='sim')simulationRun=null;main.innerHTML=key==='sim'?simulationPage(simId):key==='simulations'?simulationLibrary():key==='topic'?topic(topicId):key==='feedback'?feedback(feedbackId):key==='measure'?measurePage(measureId,params.get('stage')||'after'):key==='urgent'?urgent():key==='saved'?`<div class="page-head"><h1>موضوعاتك المحفوظة</h1><p>يمكنك الرجوع إليها من هذا الجهاز.</p></div><div class="cards">${saved.map(id=>card(byId[id])).join('')||'<div class="empty">اضغط النجمة ☆ على أي موضوع لحفظه هنا.</div>'}</div>`:key==='about'?about():key==='students'?students():key==='dashboard'?dashboard():home();document.querySelectorAll('[data-nav]').forEach(a=>{a.removeAttribute('aria-current');if(a.dataset.nav===(key==='topic'?'home':key==='sim'?'simulations':key))a.setAttribute('aria-current','page')});if(!['sim','simulations','topic','feedback','measure','urgent','saved','about','students','dashboard'].includes(key))results();document.title=(scenarioById[simId]?scenarioById[simId].title+' | ':byId[topicId]?byId[topicId].title+' | ':'')+'تمريض من أجل المجتمع';if(h==='explore')$('#explore')?.scrollIntoView();else window.scrollTo(0,0);main.focus({preventScroll:true});}
let speechChunks=[],speechIndex=0,speechActive=false,speechPaused=false,voices=[],speechEpoch=0;
function loadVoices(){if(!('speechSynthesis'in window))return;voices=window.speechSynthesis.getVoices().filter(v=>/^ar(?:[-_]|$)/i.test(v.lang));const s=$('#voice');if(s){const chosen=s.value;s.innerHTML=voices.map((v,i)=>`<option value="${i}">${esc(v.name)}${v.localService?' · على الجهاز':''}</option>`).join('');if(chosen&&voices[chosen])s.value=chosen;}}
function stopReading(){speechEpoch++;if('speechSynthesis'in window)window.speechSynthesis.cancel();speechActive=false;speechPaused=false;speechChunks=[];speechIndex=0;const p=$('#audioPlayer');if(p)p.hidden=true;const surveyButton=$('#surveyLauncher');if(surveyButton)surveyButton.hidden=false;}
function playChunk(){if(!speechActive||!speechChunks[speechIndex]){stopReading();return}const voice=voices[Number($('#voice').value)||0];if(!voice){stopReading();notify('لا يوجد صوت عربي متاح. أضف صوتًا عربيًا من إعدادات النطق.');return}const token=speechEpoch,u=new window.SpeechSynthesisUtterance(speechChunks[speechIndex]);u.voice=voice;u.lang=voice.lang;u.rate=Number($('#speed').value)||.9;u.onend=()=>{if(!speechActive||token!==speechEpoch)return;speechIndex++;if(speechIndex<speechChunks.length)playChunk();else stopReading()};u.onerror=e=>{if(token!==speechEpoch)return;if(['canceled','interrupted'].includes(e.error))return;stopReading();notify('تعذرت القراءة الصوتية. تحقق من الصوت العربي والاتصال إذا كان الصوت يحتاجه.')};$('#audioProgress').textContent=`${speechIndex+1} / ${speechChunks.length}`;window.speechSynthesis.speak(u);}
function startReading(customText,customTitle){if(!activeTopic&&typeof customText!=='string')return;if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){notify('هذا المتصفح لا يوفر القراءة الصوتية. جرب قارئ الشاشة أو متصفحًا داعمًا.');return}loadVoices();if(!voices.length){notify('لا يوجد صوت عربي متاح الآن. أضف صوتًا عربيًا من إعدادات النطق ثم أعد المحاولة.');return}stopReading();const text=typeof customText==='string'?customText:articleText(byId[activeTopic]);speechChunks=[];let chunk='';for(const word of text.split(/\s+/)){if(chunk.length+word.length>160&&chunk){speechChunks.push(chunk);chunk=''}chunk+=(chunk?' ':'')+word;}if(chunk)speechChunks.push(chunk);speechIndex=0;speechActive=true;$('#audioPlayer').hidden=false;const surveyButton=$('#surveyLauncher');if(surveyButton)surveyButton.hidden=true;$('#audioTitle').textContent=customTitle||byId[activeTopic]?.title||'قراءة الموقف';$('#pauseAudio').textContent='إيقاف مؤقت';playChunk();}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;visible=12;results()}});
document.addEventListener('change',e=>{if(e.target.id==='category'){category=e.target.value;pathFilter='all';visible=12;results()}if(e.target.dataset.kit!==undefined){let checked=readLocal('nur-community-kit',[]);if(!Array.isArray(checked))checked=[];const i=Number(e.target.dataset.kit);checked=e.target.checked?[...new Set([...checked,i])]:checked.filter(v=>v!==i);if(!writeLocal('nur-community-kit',checked))notify('التخزين غير متاح؛ العلامات لهذه الزيارة فقط.')}if(['voice','speed'].includes(e.target.id)&&speechActive){speechEpoch++;window.speechSynthesis.cancel();speechPaused=false;$('#pauseAudio').textContent='إيقاف مؤقت';playChunk()}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.path){pathFilter=b.dataset.path;category='all';query='';visible=12;$('#category').value='all';$('#search').value='';results()}if(b.dataset.healthHub){category=b.dataset.healthHub;pathFilter='all';query='';visible=12;$('#category').value=category;$('#search').value='';results();$('#resultsStart')?.scrollIntoView({block:'start'});}if(b.id==='loadMore'){visible+=12;results()}if(b.id==='allTopics'){pathFilter='all';category='all';query='';visible=ARTICLES.length;$('#search').value='';$('#category').value='all';results()}if(b.id==='clearSearch'){query='';visible=12;$('#search').value='';results();$('#search').focus()}if(b.dataset.save){const id=b.dataset.save;saved=saved.includes(id)?saved.filter(s=>s!==id):[...saved,id];writeLocal('nur-community-saved',saved);document.querySelectorAll('[data-save="'+id+'"]').forEach(el=>{el.textContent=saved.includes(id)?'★':'☆';el.setAttribute('aria-pressed',saved.includes(id));el.setAttribute('aria-label',(saved.includes(id)?'إزالة من':'إضافة إلى')+' المحفوظات')});if(location.hash==='#saved')route()}if(b.id==='fontSize'){fontLevel=(fontLevel+1)%3;applyFont();writeLocal('nur-community-font-v2',fontLevel)}if(b.id==='readTopic')startReading();if(b.id==='readSimulation')startReading(simulationReadText(),simulationRun?.scenario.title||'المحاكاة');if(b.dataset.simChoice){stopReading();if(simulationRun&&!simulationRun.pending&&!simulationRun.complete){simulationRun.choose(b.dataset.simChoice);renderSimulation();}}if(b.id==='simNext'){stopReading();if(simulationRun?.pending){simulationRun.advance();renderSimulation();}}if(b.id==='simRestart'&&simulationRun){stopReading();simulationRun=new window.CommunitySimulation.Run(simulationRun.scenario);renderSimulation();}if(b.id==='exportSimulations')download('community-simulations-'+new Date().toISOString().slice(0,10)+'.csv',simulationRecords.csv(),'text/csv;charset=utf-8');if(b.id==='clearSimulations')$('#clearSimulationsPrompt').innerHTML='<p>سيُمسح سجل المحاكاة من هذا الجهاز فقط.</p><button id="confirmClearSimulations">تأكيد المسح المحلي</button>';if(b.id==='confirmClearSimulations'){try{simulationRecords.clear();route()}catch{notify('تعذر مسح سجل المحاكاة.')}}if(b.id==='stopAudio')stopReading();if(b.id==='pauseAudio'&&speechActive){speechPaused=!speechPaused;if(speechPaused)window.speechSynthesis.pause();else window.speechSynthesis.resume();b.textContent=speechPaused?'استئناف':'إيقاف مؤقت'}if(b.id==='showSources'){const d=$('#topicSources');if(d){d.open=true;d.scrollIntoView({block:'start'});}}if(b.id==='newFeedback')route();if(b.id==='exportSurvey')download('community-pilot-survey-'+new Date().toISOString().slice(0,10)+'.csv',surveyStore.csv(),'text/csv;charset=utf-8');if(b.id==='clearSurvey')$('#clearSurveyPrompt').innerHTML='<p>سيُمسح السجل المحلي فقط. صدره أولًا إذا احتجته.</p><button id="confirmClearSurvey">تأكيد المسح</button>';if(b.id==='confirmClearSurvey'){try{surveyStore.clear();route()}catch{notify('تعذر مسح السجل المحلي.')}}if(b.id==='print')window.print();if(b.id==='share'){try{if(navigator.share)await navigator.share({title:document.title,url:location.href});else if(navigator.clipboard){await navigator.clipboard.writeText(location.href);notify('نُسخ رابط الموضوع.')}else notify('انسخ الرابط من شريط العنوان.')}catch(err){if(err.name!=='AbortError')notify('يمكنك نسخ الرابط من شريط العنوان.')}}if(b.id==='kitReset'){writeLocal('nur-community-kit',[]);document.querySelectorAll('[data-kit]').forEach(el=>el.checked=false);$('#kitStatus').textContent='بدأ تفقد جديد. لا تتغير الصلاحيات أو شروط الحفظ بمجرد وضع علامة.'}if(b.id==='kitDone'){const date=new Date().toLocaleDateString('ar-LY');writeLocal('nur-community-kit-date',date);$('#kitStatus').textContent='سجلت التفقد على هذا الجهاز بتاريخ '+date+'؛ يمكنك إعادته مجددًا.'}if(b.dataset.water){document.querySelectorAll('[data-water]').forEach(el=>el.setAttribute('aria-pressed',el===b));$('#waterChoice').textContent='اختيارك لهذه الزيارة: '+b.dataset.water+' — اتبع أي تقييد سوائل وصفه فريقك.'}if(b.id==='exportMetrics')download('community-measurements-'+new Date().toISOString().slice(0,10)+'.csv',measurement.csv(),'text/csv;charset=utf-8');if(b.id==='clearMetrics')$('#clearMetricsPrompt').innerHTML='<p>سيُمسح سجل القياس من هذا الجهاز فقط. صدره أولًا إن كنت تحتاجه.</p><button id="confirmClearMetrics">تأكيد المسح المحلي</button>';if(b.id==='confirmClearMetrics'){try{measurement.clear();route()}catch{notify('تعذر مسح السجل على هذا المتصفح.')}}if(b.id==='resetPreferences'){saved=[];fontLevel=0;writeLocal('nur-community-saved',[]);writeLocal('nur-community-font-v2',0);applyFont();notify('مُسحت المفضلة وإعدادات النص. لم يتغير سجل القياس.')}if(b.id==='install'&&installEvent){await installEvent.prompt();installEvent=null;b.hidden=true;}});
document.addEventListener('submit',e=>{if(e.target.id==='simulationForm'){e.preventDefault();saveSimulation(e.target);}if(e.target.id==='feedbackForm'){e.preventDefault();prepareFeedback(e.target);}if(e.target.id==='measureForm'){e.preventDefault();const f=new FormData(e.target),a=byId[e.target.dataset.topic];if(!a||!f.get('consent')||f.get('answer')===null)return;const stage=String(f.get('stage')),score=Number(f.get('answer'))===a.question[2]?1:0,campaign=String(f.get('campaign')||'').trim().slice(0,24);let row;try{row=measurement.save({topic:a.id,release:R.version,assessment:a.id+'-q1-v1',stage,score,confidence:String(f.get('confidence')),behavior:String(f.get('behavior')),campaign,linkPrevious:!!f.get('linkPrevious')})}catch{notify('تعذر الحفظ. قد يكون التخزين ممتلئًا أو غير متاح؛ صدّر السجل إذا لزم.');return}const url=feedbackLink({message:['تمريض من أجل المجتمع','رمز المبادرة: NUR_COMMUNITY_MEASURE','الموضوع: '+a.title,'معرف الموضوع: '+a.id,'المرحلة: '+({before:'قبل القراءة',after:'بعد القراءة',followup:'متابعة لاحقة'}[stage]),'السؤال: '+a.question[0],'الإجابة المختارة: '+a.question[1][Number(f.get('answer'))],'الثقة: '+({'1':'غير متأكد','2':'أحتاج توضيحًا','3':'أستطيع شرح الفكرة'}[row.confidence]),'السلوك: '+({plan:'أنوي التطبيق',done:'طبقت خطوة',notyet:'لم أطبق بعد',notrelevant:'لا ينطبق الآن'}[row.behavior]),'رمز النشاط: '+(row.campaign||'قراءة فردية'),'التاريخ: '+new Date(row.time).toISOString(),'مرجع السجل: '+row.id,'مرجع الدورة: '+row.cycle,'إصدار المحتوى: '+row.release,'نسخة السؤال: '+row.assessment].join('\n'),recurrence:'قياس اختياري متكرر؛ المرحلة '+stage,suggestion:'يرجى إدراج السجل ضمن تقييم مبادرة التوعية الصحية المجتمعية.'});$('#measureResult').innerHTML=`<section class="measurement-result"><h2>حُفظت المشاركة على هذا الجهاز</h2><p>${stage==='before'?'اقرأ الموضوع ثم عد للقياس البعدي. لا نعرض الحل في القياس القبلي.':'الفكرة الصحيحة: '+esc(a.question[1][a.question[2]])}</p><p>لم تُرسل للكلية. إن رغبت افتح الرابط وأكمل الإرسال في النموذج.</p><div class="choice-row"><a class="button primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">شارك النتيجة مع الكلية ↗</a><a class="button" href="#topic=${a.id}">العودة للموضوع</a><a class="button" href="#measure=${a.id}&stage=${stage==='before'?'after':'followup'}">مشاركة أخرى</a></div><p class="form-note">سجل ${esc(row.id)} · ${new Date(row.time).toLocaleString('ar-LY')}. المشاركة الجديدة لا تُحسب تلقائيًا كشخص جديد.</p></section>`;$('#measureResult').scrollIntoView({block:'center'});}});
function simulationCard(s){return `<article class="story-card sim-card"><a class="card-art" href="#sim=${s.id}">${Art.render(s.art,s.title)}</a><div class="card-copy"><span class="label">موقف متفرع · بلا مؤقت</span><h3><a href="#sim=${s.id}">${esc(s.title)}</a></h3><p>${esc(s.intro)}</p><a class="button soft" href="#sim=${s.id}">جرّب قرارك ←</a></div></article>`;}
function simulationTeaser(){return `<section class="simulation-teaser"><div class="section-title"><div><span class="label">تعلم بالموقف والاختيار</span><h2>ماذا ستفعل لو حدث هذا؟</h2><p>اختر تصرفًا، وافهم نتيجته، ثم أكمل الموقف. يمكنك إعادة المحاولة.</p></div><a class="button" href="#simulations">كل المواقف (${window.CommunityScenarios.items.length}) ←</a></div><div class="cards">${window.CommunityScenarios.items.slice(0,3).map(simulationCard).join('')}</div></section>`;}
function simulationLibrary(){return `<section class="page-head"><span class="label">محاكاة للتعلم اليومي</span><h1>قرار صغير قد يحميك ويحمي غيرك</h1><p>ثمانية مواقف من البيت والحي والتطوع. اختيارك يغير ما يحدث في الخطوة التالية، وسترى تفسيرًا بعد كل قرار.</p></section><div class="simulation-note"><b>تدرّب بالاختيارات فقط</b><p>لا تحتاج معدات أو تجربة فعلية. لا يوجد عد تنازلي، ويمكنك الاستماع أو تكبير النص. التدريب لا يمنح شهادة كفاءة أو أهلية طبية.</p><a href="#dashboard">سجل الجولات التي اخترت حفظها</a></div><div class="cards simulation-library">${window.CommunityScenarios.items.map(simulationCard).join('')}</div>`;}
function simulationPage(id){const s=scenarioById[id];if(!s)return '<div class="empty"><h1>هذا الموقف غير موجود</h1><a href="#simulations">استعرض المواقف</a></div>';if(!simulationRun||simulationRun.scenario.id!==id)simulationRun=new window.CommunitySimulation.Run(s);return simulationContent();}
function simulationContent(){const run=simulationRun,s=run.scenario;return `<article class="simulation-page"><a class="back" href="#simulations">→ المواقف التفاعلية</a><div class="sim-heading"><div><span class="label">تعلم دون استعجال · يمكنك الإعادة</span><h1 id="simHeading" tabindex="-1">${esc(s.title)}</h1><p>${esc(s.intro)}</p><button class="button" id="readSimulation">◖ استمع للموقف الحالي</button></div><div class="sim-art">${Art.render(s.art,s.title)}</div></div>${run.complete?simulationResult():simulationDecision()}<details class="source-details"><summary>مصادر هذا الموقف وحالة المراجعة</summary><ul>${s.sources.map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a></li>`).join('')}</ul><p>نسخة السيناريو ${esc(s.version)} · إصدار التطبيق ${R.version}. مواقف تعليمية أولية بانتظار مراجعة الكلية.</p></details><p><a href="#feedback=${s.id}">أبلغنا عن غموض أو خطأ في هذا الموقف</a></p></article>`;}
function simulationDecision(){const run=simulationRun,node=run.scenario.nodes[run.current],chosen=run.pending;return `<section class="sim-stage" aria-labelledby="simQuestion"><div class="sim-progress">قرار ${run.decisions.length+(chosen?0:1)} · يتغير طول الموقف بحسب اختياراتك</div>${node.context?`<p class="sim-context">${esc(node.context)}</p>`:''}<h2 id="simQuestion">${esc(node.prompt)}</h2><div class="sim-options">${node.choices.map((c,i)=>`<button class="sim-option ${chosen?.id===c.id?'selected':''}" data-sim-choice="${esc(c.id)}" ${chosen?'disabled':''}><span class="option-number" aria-hidden="true">${i+1}</span><span>${esc(c.label)}</span></button>`).join('')}</div>${chosen?`<section class="sim-feedback ${chosen.safe?'safe':'review-choice'}" role="status"><b>${chosen.safe?'اختيار يحافظ على السلامة':'لنراجع هذا الاختيار'}</b><p>${esc(chosen.feedback)}</p><button class="button primary" id="simNext">${chosen.next===null?'راجع ما تعلمته ←':'الخطوة التالية ←'}</button></section>`:'<p class="muted">اختر ما تراه مناسبًا. لن يُحفظ اختيارك أو يُرسل تلقائيًا.</p>'}${nodeRefs(run.scenario,node)}</section>`;}
function simulationResult(){const run=simulationRun,s=run.scenario,sum=run.summary();return `<section class="sim-result"><span class="label">انتهى الموقف · يبدأ التطبيق في الحياة</span><h2>خذ معك التصرف الآمن</h2><p class="sim-score">${sum.safe} من ${sum.decisions} قراراتك كانت آمنة في هذا المسار.</p><p>${sum.critical?'ظهرت اختيارات قد تسبب خطرًا مهمًا. اقرأ تفسيرها أدناه ثم أعد الموقف للتدرب.':'راجع أسباب الاختيارات، ثم شارك الفكرة مع من يحتاجها.'} يختلف عدد القرارات بين المسارات؛ النتيجة للتعلم وليست ترتيبًا للمشاركين.</p><details class="decision-review" open><summary>راجع قراراتك بالترتيب</summary><ol>${run.decisions.map(d=>{const n=s.nodes[d.node],c=n.choices.find(x=>x.id===d.choice);return `<li><b>${esc(n.prompt)}</b><p>اخترت: ${esc(c.label)}</p><p class="${d.safe?'safe-text':'review-text'}">${esc(c.feedback)}</p></li>`;}).join('')}</ol></details><div class="choice-row"><button class="button primary" id="simRestart">أعد الموقف للتدرب</button><a class="button" href="#simulations">موقف آخر</a>${s.topics.filter(id=>byId[id]).map(id=>`<a class="button" href="#topic=${id}">${esc(byId[id].title)}</a>`).join('')}</div></section><section class="panel sim-save"><h2>تريد حفظ هذه الجولة للمتابعة؟</h2><p>هذا اختياري. تبقى الجولة على هذا الجهاز إلى أن تصدرها أو تختار مشاركتها. يمكنك حفظ جولات لاحقة، ولا يُعد تكرار التدريب شخصًا جديدًا.</p>${run.saved?simulationSaved(run.saved):`<form id="simulationForm"><label class="field" for="simPhase">نوع الجولة</label><select id="simPhase" name="phase"><option value="practice">تدرب الآن</option><option value="later">عودة للتعلم في وقت لاحق</option></select><label class="field" for="simCampaign">رمز نشاط الطلاب — اختياري</label><input id="simCampaign" name="campaign" maxlength="24" autocomplete="off" placeholder="اتركه فارغًا للاستخدام الفردي"><label class="consent"><input type="checkbox" name="linkPrevious"><span>أنا نفس المشارك في آخر جولة محفوظة لهذا الموقف على الجهاز خلال 30 يومًا، وأريد ربط الجولتين.</span></label><label class="consent"><input type="checkbox" name="consent" required><span>أوافق على حفظ وقت الجولة واختياراتها ونسختها محليًا، دون اسم أو معلومات صحية.</span></label><button class="button primary" type="submit">احفظ هذه الجولة بإذني</button><p id="simSaveStatus" role="status"></p></form>`}</section>`;}
function renderSimulation(){if(!simulationRun)return;$('#main').innerHTML=simulationContent();$('#simHeading')?.focus({preventScroll:true});}
function simulationReadText(){const r=simulationRun;if(!r)return '';const s=r.scenario;if(r.complete)return [s.title,'انتهى الموقف',...r.decisions.flatMap(d=>{const n=s.nodes[d.node],c=n.choices.find(x=>x.id===d.choice);return[n.prompt,'اخترت',c.label,c.feedback]})].join('. ');const n=s.nodes[r.current];return[s.title,s.intro,n.context||'',n.prompt,...n.choices.map((c,i)=>'الخيار '+(i+1)+': '+c.label),...(r.pending?['اخترت',r.pending.label,r.pending.feedback]:[])].join('. ');}
function simulationSaved(row){const s=scenarioById[row.scenario],sum=simulationRun?.summary(),message=['تمريض من أجل المجتمع','رمز المبادرة: NUR_COMMUNITY_SIMULATION','الموقف: '+s.title,'معرف السيناريو: '+s.id,'نسخة السيناريو: '+row.scenarioVersion,'إصدار التطبيق: '+row.release,'مرجع الجولة: '+row.id,'جولة سابقة ربطها المشارك: '+(row.previousAttempt||'مستقلة'),'نوع الجولة: '+(row.phase==='later'?'عودة لاحقة':'تدرب'),'رمز النشاط: '+(row.campaign||'استخدام فردي'),'الوقت: '+new Date(row.time).toISOString(),...row.decisions.map((d,i)=>{const n=s.nodes[d.node],c=n.choices.find(x=>x.id===d.choice);return 'قرار '+(i+1)+' ['+d.node+'/'+d.choice+']: '+c.label+' — '+(d.safe?'آمن':'يحتاج مراجعة')+(d.critical?'؛ خطر مهم':'');})].join('\n');const url=feedbackLink({message,recurrence:'جولة محاكاة تعليمية قابلة للتكرار',suggestion:'تُحلل حسب نسخة الموقف والمسار، ولا تعني شهادة كفاءة أو شخصًا جديدًا.'});return `<div class="measurement-result" role="status"><b>حُفظت الجولة على هذا الجهاز</b><p>لم تُرسل للكلية. إن رغبت، افتح النموذج وأكمل الإرسال بنفسك.</p><a class="button primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">شارك الجولة مع الكلية ↗</a><a class="button" href="#dashboard">سجل المتابعة</a><p class="form-note">مرجع الجولة: ${esc(row.id)}</p></div>`;}
function saveSimulation(form){if(!simulationRun?.complete)return;const f=new FormData(form);try{simulationRecords.save(simulationRun,{consent:!!f.get('consent'),release:R.version,campaign:String(f.get('campaign')||'').trim().slice(0,24),phase:String(f.get('phase')||'practice'),linkPrevious:!!f.get('linkPrevious')});renderSimulation();}catch{notify('تعذر الحفظ. تحقق من الموافقة وإتاحة مساحة التخزين؛ يمكنك متابعة التعلم دون حفظ.');}}
function simulationDashboard(){const s=simulationRecords.summary();return `<section class="panel"><span class="label">سجل مستقل للمحاكاة</span><h2>جولات المواقف على هذا الجهاز</h2><div class="metric-grid"><div><b>${s.attempts}</b><span>جولات محفوظة بإذن</span></div><div><b>${s.decisions}</b><span>قرارات داخل هذه الجولات</span></div><div><b>${s.linked}</b><span>جولات مرتبطة بإقرار المشارك</span></div><div><b>${s.later}</b><span>جولات وصفها المشارك كعودة لاحقة</span></div></div><p>كل صف في CSV يمثل قرارًا؛ احسب الجولات من معرفاتها المميزة. لا تعني الأعداد أشخاصًا أو وصولًا مجتمعيًا، ولا تقارن النتائج بين مسارات أو نسخ مختلفة دون بيان. الربط ليس إثبات هوية أو أثر سببي.</p><div class="choice-row"><button class="button primary" id="exportSimulations">تصدير جولات المحاكاة CSV</button><button id="clearSimulations">مسح سجل المحاكاة</button><a class="button" href="#simulations">تدرب من جديد</a></div><p id="clearSimulationsPrompt" role="status"></p></section>`;}


function healthHubs(){return `<div class="health-hubs" aria-label="وصول مباشر إلى المجالات الصحية">${R.healthHubs.map(h=>`<button class="health-hub" data-health-hub="${h.value}" aria-pressed="${category===h.value}"><span class="hub-art" aria-hidden="true">${Art.render(h.art,h.label)}</span><span>${esc(h.label)}</span></button>`).join('')}</div>`;}
function learningSections(a){return (a.learningSections||[]).map(s=>`<section class="learning-section ${a.id==='diabetes-high-correction'?'dose-education':''}"><h2>${esc(s.title)}</h2>${s.body?`<p>${medicalText(s.body)}</p>`:''}${s.bullets?.length?listHTML(s.bullets):''}${lessonRefs(a,s)}</section>`).join('');}
function relatedTopics(a){const ids=(a.related||[]).filter(id=>byId[id]&&id!==a.id);return ids.length?`<section class="related-topics"><span class="label">أكمل ما تحتاجه</span><h2>${a.id.startsWith('diabetes')?'أدلة السكري المترابطة':'موضوعات مرتبطة'}</h2><div class="related-grid">${ids.map(id=>`<a href="#topic=${id}"><span aria-hidden="true">${Art.render(byId[id].art,byId[id].title)}</span><b>${esc(byId[id].title)}</b><span aria-hidden="true">←</span></a>`).join('')}</div></section>`:'';}


function diabetesShortcuts(a){if(a.id!=='diabetes')return '';return `<section class="diabetes-shortcuts" aria-label="ابدأ من حاجتك في السكري"><b>ابدأ مما تحتاجه الآن</b><div class="choice-row">${[['diabetes-food-portions','الطعام وكمياته'],['diabetes-high-correction','ارتفاع السكر والتصحيح'],['diabetes-sick-days','القيء والإسهال والجفاف'],['diabetes-hypoglycemia','هبوط السكر']].map(([id,label])=>`<a class="button" href="#topic=${id}">${label} ←</a>`).join('')}</div></section>`;}


function medicalText(value){return esc(value).replace(/\(250 − 150\) ÷ 50 = 2/g,match=>'<bdi dir="ltr" class="formula-inline">'+match+'</bdi>').replace(/(?:[0-9]+(?:\.[0-9]+)?\s+)?(?:mg\/dL|mmol\/L)\b/g,match=>'<bdi dir="ltr">'+match+'</bdi>');}

function surveyIcon(){return `<svg viewBox='0 0 24 24' width='23' height='23' fill='none' stroke='currentColor' stroke-width='1.8' aria-hidden='true'><path d='M4 4h16v12H9l-5 4V4Z'/><path d='M8 8h8M8 12h5'/></svg>`;}
function trialNotice(){return `<section class='trial-notice'><div><span class='label'>نطوّرها بمشاركتك</span><h2>نسخة تجريبية لاختبارها مع المجتمع</h2><p>نختبر الجوانب التقنية وسهولة الاستخدام، ونجمع آراءكم حول جودة المحتوى وفائدته، وأفكاركم ومقترحاتكم للتحسين.</p><p>يمكنك المشاركة بعد كل تجربة أو موضوع، حتى لو سبق أن شاركت. النقد والتصحيح والتعليقات مرحّب بها.</p></div><a class='button primary' href='#feedback'>${surveyIcon()} شارك في استبيان التجربة</a></section>`;}
function surveySelect(id,name,label,options){return `<label class='field' for='${id}'>${label}</label><select id='${id}' name='${name}'><option value=''>اختر إن رغبت</option>${options.map(([v,t])=>`<option value='${v}'>${t}</option>`).join('')}</select>`;}
function feedback(id){const a=byId[id]||scenarioById[id];return `<div class='narrow'><div class='page-head'><span class='label'>استبيان التجربة · المشاركة متاحة أكثر من مرة</span><h1>رأيك يغيّر ما نطوّره</h1><p>هذه نسخة تجريبية لاختبار التشغيل وسهولة الاستخدام، وتقييم جودة المحتوى ونفعه، وجمع النقد والملاحظات والأفكار والمقترحات. ${a?'حول: '+esc(a.title):''}</p><p>أجب عما جرّبته فقط. لا نطلب اسمًا أو معلومات صحية شخصية.</p></div><form class='panel form-panel' id='feedbackForm' data-topic='${a?.id||'general'}'><label class='field' for='feedbackType'>ما نوع مشاركتك؟</label><select id='feedbackType' name='kind'><option>تقييم التجربة والمحتوى</option><option>نقد أو ملاحظة</option><option>تصحيح معلومة أو طلب مصدر</option><option>مشكلة تقنية أو صعوبة استخدام</option><option>فكرة أو موضوع مقترح</option></select>${surveySelect('surveyEase','ease','كيف وجدت استخدام التطبيق؟',[['easy','سهل وواضح'],['some','مقبول مع بعض الصعوبة'],['hard','صعب ويحتاج تحسينًا'],['nottried','لم أجرب بما يكفي']])}${surveySelect('surveyClarity','clarity','كيف وجدت وضوح المحتوى الذي قرأته؟',[['clear','واضح ومفهوم'],['some','أجزاء منه تحتاج تبسيطًا'],['unclear','غير واضح لي'],['notread','لم أقرأ بما يكفي']])}${surveySelect('surveyUsefulness','usefulness','ما مدى فائدته لك؟',[['useful','وجدت معلومة أو خطوة مفيدة لي'],['others','قد يفيد شخصًا آخر أعرفه'],['limited','فائدته محدودة ويحتاج تطويرًا'],['unsure','لا أستطيع تقييمه بعد']])}<fieldset><legend>هل واجهت مشكلة؟ اختياري ويمكن اختيار أكثر من واحدة</legend><div class='survey-issues'>${[['display','الخط أو عرض الصفحة'],['audio','القراءة الصوتية'],['search','البحث والوصول للموضوع'],['simulation','المحاكاة'],['offline','الاستخدام دون اتصال'],['slow','بطء أو تعطل'],['other','أخرى سأشرحها أدناه']].map(([v,t])=>`<label><input type='checkbox' name='issues' value='${v}'><span>${t}</span></label>`).join('')}</div></fieldset><label class='field' for='feedbackText'>نقدك أو ملاحظتك أو تصحيحك — اختياري</label><textarea id='feedbackText' name='message' maxlength='700' placeholder='ما الذي لم يعمل؟ ما المعلومة التي تحتاج تصحيحًا أو مصدرًا؟'></textarea><label class='field' for='feedbackImprove'>فكرة أو اقتراح للتحسين — اختياري</label><textarea id='feedbackImprove' name='suggestion' maxlength='300' placeholder='ما الذي سيجعل التطبيق أنفع لك وللمجتمع؟'></textarea><label class='consent'><input type='checkbox' name='surveyConsent'><span>أوافق اختياريًا على حفظ هذه المشاركة على هذا الجهاز للمتابعة والتصدير. تركها دون علامة لا يمنع تجهيز المشاركة للكلية.</span></label><p class='form-note'>لا تكتب بيانات مريض أو اسم شخص. عند التجهيز يظهر رابط إلى قناة ملاحظات الكلية الحالية بنص إجاباتك؛ لا تكتمل المشاركة المركزية حتى تضغط «إرسال» هناك. يمكنك تجهيز مشاركة جديدة في كل مرة.</p><button class='button primary' type='submit'>جهّز مشاركتي</button><div id='feedbackStatus' role='status'></div></form></div>`;}
function prepareFeedback(form){const f=new FormData(form),comment=String(f.get('message')||'').trim(),suggestion=String(f.get('suggestion')||'').trim(),issues=f.getAll?f.getAll('issues').map(String):[],input={release:R.version,context:form.dataset.topic||'general',kind:String(f.get('kind')||'نقد أو ملاحظة'),ease:String(f.get('ease')||''),clarity:String(f.get('clarity')||''),usefulness:String(f.get('usefulness')||''),issues,comment,suggestion};if(!comment&&!suggestion&&!issues.length&&!input.ease&&!input.clarity&&!input.usefulness){$('#feedbackStatus').textContent='اختر تقييمًا أو اكتب ملاحظة أو اقتراحًا أولًا.';return;}let row=null;if(f.get('surveyConsent')){try{row=surveyStore.save(input,{consent:true,id:form.dataset.surveyId||undefined});form.dataset.surveyId=row.id;}catch{$('#feedbackStatus').textContent='تعذر الحفظ المحلي. يمكنك إلغاء خيار الحفظ ثم تجهيز المشاركة، أو تصدير السجل السابق إذا امتلأ.';return;}}
 const labels={ease:{easy:'سهل وواضح',some:'مقبول مع بعض الصعوبة',hard:'صعب',nottried:'لم يجرب بما يكفي'},clarity:{clear:'واضح',some:'يحتاج تبسيطًا',unclear:'غير واضح',notread:'لم يقرأ بما يكفي'},usefulness:{useful:'مفيد لي',others:'قد يفيد غيري',limited:'فائدته محدودة',unsure:'لا يستطيع تقييمه'}},issueLabels={display:'العرض والخط',audio:'الصوت',search:'البحث',simulation:'المحاكاة',offline:'دون اتصال',slow:'البطء أو التعطل',other:'أخرى'};const message=['تمريض من أجل المجتمع','رمز المبادرة: NUR_COMMUNITY_FEEDBACK','نوع الأداة: NUR_COMMUNITY_PILOT_SURVEY','الموضوع: '+(byId[input.context]?.title||scenarioById[input.context]?.title||'التطبيق عمومًا'),'نوع المشاركة: '+input.kind,'سهولة الاستخدام: '+(labels.ease[input.ease]||'لم يجب'),'وضوح المحتوى: '+(labels.clarity[input.clarity]||'لم يجب'),'فائدة المحتوى: '+(labels.usefulness[input.usefulness]||'لم يجب'),'المشكلات التقنية: '+(issues.map(x=>issueLabels[x]||x).join('، ')||'لم يحدد'),'الملاحظة: '+(comment||'لم يكتب'),'المقترح: '+(suggestion||'لم يكتب'),'إصدار المحتوى: '+R.version,'الوقت: '+new Date().toISOString(),...(row?['مرجع المشاركة المحلية: '+row.id]:[])].join('\n');const url=feedbackLink({message,suggestion,recurrence:'استبيان النسخة التجريبية؛ المشاركة قابلة للتكرار بعد كل تجربة أو موضوع'});$('#feedbackStatus').innerHTML=`<div class='survey-ready'><b>${row?'حُفظت المشاركة محليًا وجهزت للمشاركة':form.dataset.surveyId?'جهزت التعديلات دون حفظ جديد؛ تبقى المشاركة التي حفظتها سابقًا على الجهاز':'جهزت مشاركتك دون حفظ محلي'}</b><p>لم تُرسل الرسالة إلى الكلية بعد؛ افتح النموذج ثم اضغط «إرسال» هناك.</p><a class='button primary' href='${esc(url)}' target='_blank' rel='noopener noreferrer'>افتح نموذج الكلية وأكمل الإرسال ↗</a><button id='newFeedback' type='button' class='button'>ابدأ مشاركة جديدة</button><p class='form-note'>تعديل الإجابات وإعادة تجهيزها يحدث المشاركة المحلية نفسها. زر «مشاركة جديدة» يبدأ سجلًا مستقلًا. الأعداد تمثل مشاركات وليست أشخاصًا.</p></div>`;$('#feedbackStatus').scrollIntoView({block:'center'});}
function surveyDashboard(){const s=surveyStore.summary();return `<section class='panel'><span class='label'>استبيان النسخة التجريبية</span><h2>المشاركات المحفوظة بإذن على هذا الجهاز</h2><div class='metric-grid'><div><b>${s.records}</b><span>مشاركات محفوظة، لا أشخاص فريدون</span></div><div><b>${s.easy} / ${s.easeEvaluated}</b><span>وجدوا الاستخدام سهلًا من الذين قيّموه</span></div><div><b>${s.clear} / ${s.clarityEvaluated}</b><span>وجدوا المحتوى واضحًا من الذين قيّموه</span></div><div><b>${s.useful} / ${s.usefulnessEvaluated}</b><span>وجدوه مفيدًا لهم من الذين قيّموا فائدته</span></div></div><p>هذه مشاركات اختيارية محلية؛ التكرار والجهاز المشترك يؤثران في الأعداد، ولا تقيس الوصول العام أو الأثر الصحي. المشاركات المرسلة للنموذج المركزي منفصلة.</p><div class='choice-row'><button id='exportSurvey' class='button primary'>تصدير استبيان التجربة CSV</button><button id='clearSurvey'>مسح سجل الاستبيان</button><a class='button' href='#feedback'>مشاركة أخرى</a></div><p id='clearSurveyPrompt' role='status'></p></section>`;}
function referenceDetails(refs,label){const unique=[...new Map(refs.filter(Boolean).map(s=>[s[2],s])).values()];if(!unique.length)return '';return `<details class='section-references'><summary>${label}</summary><ul>${unique.map(s=>`<li><a href='${esc(s[2])}' target='_blank' rel='noopener noreferrer'><b>${esc(s[0])}</b> · ${esc(s[1])} ↗</a></li>`).join('')}</ul></details>`;}
function sectionRefs(a,key){const specific=a.sectionSources?.[key];return referenceDetails((specific?.length?specific:a.sources).map(k=>SOURCES[k]),specific?.length?'مصادر هذا الجزء':'مراجع الموضوع');}
function lessonRefs(a,s){return referenceDetails((s.sources?.length?s.sources:a.sources).map(k=>SOURCES[k]),s.sources?.length?'مصادر هذا الجزء':'مراجع الموضوع');}
function articleSourceKeys(a){return [...new Set([...a.sources,...Object.values(a.sectionSources||{}).flat(),...(a.learningSections||[]).flatMap(s=>s.sources||[])])];}
function nodeRefs(s,n){const urls=n.sources||[],refs=urls.length?urls.map(u=>s.sources.find(x=>x.url===u)):s.sources;return referenceDetails(refs.filter(Boolean).map(x=>['المصدر الرسمي',x.title,x.url]),urls.length?'مصادر إرشادات هذا الموقف':'مراجع الموقف');}

window.addEventListener('hashchange',route);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;$('#install').hidden=false});if('speechSynthesis'in window){window.speechSynthesis.addEventListener?.('voiceschanged',loadVoices);loadVoices();}applyFont();route();
if('serviceWorker'in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(async()=>{await navigator.serviceWorker.ready;const cache=await caches.open('nur-community-v0.5.1');$('#connection').textContent=await cache.match(new URL('./rich-content.js',location.href).href)?'القراءة دون اتصال متاحة للمواد المضمنة':'اتصل مرة أخرى لإكمال تحميل الإصدار الجديد';}).catch(()=>$('#connection').textContent='لم يكتمل الحفظ دون اتصال؛ افتح النسخة متصلًا.')}else $('#connection').textContent='التثبيت والحفظ دون اتصال يحتاجان النسخة المستضافة عبر HTTPS.';
